/// Why a core call failed, as Kotlin sees it: an exception whose message is the text below.
#[derive(Debug, thiserror::Error, uniffi::Error)]
#[uniffi(flat_error)]
pub enum CoreError {
    #[error("{0}")]
    Network(String),
    #[error("{0}")]
    BadAnswer(String),
}

impl From<zcore::Error> for CoreError {
    fn from(error: zcore::Error) -> Self {
        match error {
            zcore::Error::Network(message) => CoreError::Network(message),
            error @ zcore::Error::BadAnswer(_) => CoreError::BadAnswer(error.to_string()),
        }
    }
}

/// A time as the players show it: "4:05", "1:02:03" (`zcore::player::clock`).
#[uniffi::export]
pub fn clock(seconds: f64) -> String {
    zcore::player::clock(seconds)
}

/// A file in a cache folder: its name, size and when it was written (seconds since 1970).
#[derive(Debug, uniffi::Record)]
pub struct CachedFile {
    pub name: String,
    pub size: u64,
    pub at: f64,
}

/// The most the picture cache keeps on disk (`zcore::cache::IMAGE_DISK_CAP`).
#[uniffi::export]
pub fn cache_image_disk_cap() -> u64 {
    zcore::cache::IMAGE_DISK_CAP
}

/// The share of memory decoded pictures may fill (`zcore::cache::image_memory_share`).
#[uniffi::export]
pub fn cache_image_memory_share(tv: bool, low_ram: bool) -> f64 {
    zcore::cache::image_memory_share(tv, low_ram)
}

/// The files to delete so a cache folder fits in the core's cap, oldest first (`zcore::cache::evict`).
#[uniffi::export]
pub fn cache_evict(files: Vec<CachedFile>) -> Vec<String> {
    let files: Vec<(String, u64, f64)> = files.into_iter().map(|f| (f.name, f.size, f.at)).collect();
    zcore::cache::evict(&files, zcore::cache::DISK_CAP)
}

/// The words of the controls every page shares (`zcore::words`).
#[derive(Debug, uniffi::Record)]
pub struct ShellWords {
    pub back: String,
    pub try_again: String,
    pub profiles_and_settings: String,
    pub say_a_title: String,
}

#[uniffi::export]
pub fn shell_words() -> ShellWords {
    let w = zcore::words::words();
    ShellWords { back: w.back, try_again: w.try_again, profiles_and_settings: w.profiles_and_settings, say_a_title: w.say_a_title }
}

/// The file a kept page is in, without its extension (`zcore::cache::file_name`).
#[uniffi::export]
pub fn cache_file_name(key: String) -> String {
    zcore::cache::file_name(&key)
}

