// ---------- downloads (`zcore::downloads`) ----------

use zcore::downloads as dl;

/// A chapter's folder name (`zcore::downloads::chapter_folder`).
#[uniffi::export]
pub fn chapter_folder(path: String) -> String {
    dl::chapter_folder(&path)
}

/// Why a download stopped, in the words every app shows (`zcore::downloads`).
#[derive(Debug, uniffi::Record)]
pub struct DownloadWords {
    pub cant: String,
    pub full: String,
    pub dropped: String,
    pub not_answering: String,
    pub cant_save: String,
    pub chapter_not_out: String,
    pub page_missing: String,
}

/// The download failure words (`zcore::downloads::CANT` and the rest).
#[uniffi::export]
pub fn download_words() -> DownloadWords {
    DownloadWords {
        cant: dl::CANT.into(),
        full: dl::FULL.into(),
        dropped: dl::DROPPED.into(),
        not_answering: dl::NOT_ANSWERING.into(),
        cant_save: dl::CANT_SAVE.into(),
        chapter_not_out: dl::CHAPTER_NOT_OUT.into(),
        page_missing: dl::PAGE_MISSING.into(),
    }
}

/// A size as Downloads says it ("1.2 GB").
#[uniffi::export]
pub fn size_words(bytes: u64) -> String {
    dl::size_words(bytes)
}
